    if((m=text.match(/^Yes, allow downloads from (.+) in this conversation$/)))return `是，在本会话中允许从 ${m[1]} 下载`;
    if((m=text.match(/^Yes, always allow downloads from (.+)$/)))return `是，始终允许从 ${m[1]} 下载`;
